/**
 * A utility class for building a list of Node.js Buffer instances.
 *
 * BufferList supports chaining by returning `this` from all `add*` methods,
 * allowing multiple buffers and values to be accumulated and then joined into
 * a single Buffer. It is primarily used in test helpers for constructing
 * PostgreSQL protocol packets.
 */
export default class BufferList {
  /**
   * Creates a new BufferList.
   *
   * @param buffers - Optional initial array of Buffer instances. Defaults to an empty array.
   */
  constructor(public buffers: Buffer[] = []) {}

  /**
   * Adds a Buffer to the list.
   *
   * @param buffer - The Buffer instance to add.
   * @param front - If true, inserts the buffer at the front of the list; otherwise appends it.
   * @returns The BufferList instance, for chaining.
   */
  public add(buffer: Buffer, front?: boolean): this {
    this.buffers[front ? 'unshift' : 'push'](buffer)
    return this
  }

  /**
   * Adds a 16-bit signed integer as two big-endian bytes.
   *
   * @param val - The integer value to encode.
   * @param front - If true, inserts at the front of the list; otherwise appends.
   * @returns The BufferList instance, for chaining.
   */
  public addInt16(val: number, front?: boolean): this {
    // Encode the value as two big-endian bytes: high byte, then low byte.
    return this.add(Buffer.from([val >>> 8, val >>> 0]), front)
  }

  /**
   * Calculates the total byte length of all buffers currently in the list.
   *
   * @returns The combined byte length.
   */
  public getByteLength(): number {
    return this.buffers.reduce(function (previous, current) {
      return previous + current.length
    }, 0)
  }

  /**
   * Adds a 32-bit signed integer as four big-endian bytes.
   *
   * @param val - The integer value to encode.
   * @param first - If true, inserts at the front of the list; otherwise appends.
   * @returns The BufferList instance, for chaining.
   */
  public addInt32(val: number, first?: boolean): this {
    return this.add(
      // Encode the value as four big-endian bytes, masking each byte to 0xff.
      Buffer.from([
        (val >>> 24) & 0xff,
        (val >>> 16) & 0xff,
        (val >>> 8) & 0xff,
        (val >>> 0) & 0xff,
      ]),
      first
    )
  }

  /**
   * Adds a null-terminated C string (UTF-8 encoded).
   *
   * @param val - The string value to encode.
   * @param front - If true, inserts at the front of the list; otherwise appends.
   * @returns The BufferList instance, for chaining.
   */
  public addCString(val: string, front?: boolean): this {
    const len = Buffer.byteLength(val)
    const buffer = Buffer.alloc(len + 1)
    buffer.write(val)
    // Append the null terminator (0x00) immediately after the string content.
    buffer[len] = 0
    return this.add(buffer, front)
  }

  /**
   * Adds a raw string (UTF-8 encoded) without a null terminator.
   *
   * @param val - The string value to encode.
   * @param front - If true, inserts at the front of the list; otherwise appends.
   * @returns The BufferList instance, for chaining.
   */
  public addString(val: string, front?: boolean): this {
    const len = Buffer.byteLength(val)
    const buffer = Buffer.alloc(len)
    buffer.write(val)
    return this.add(buffer, front)
  }

  /**
   * Adds a single UTF-8 character.
   *
   * @param char - The character to encode.
   * @param first - If true, inserts at the front of the list; otherwise appends.
   * @returns The BufferList instance, for chaining.
   */
  public addChar(char: string, first?: boolean): this {
    return this.add(Buffer.from(char, 'utf8'), first)
  }

  /**
   * Adds a single byte.
   *
   * @param byte - The byte value to add.
   * @returns The BufferList instance, for chaining.
   */
  public addByte(byte: number): this {
    return this.add(Buffer.from([byte]))
  }

  /**
   * Joins all accumulated buffers into a single Buffer.
   *
   * When `appendLength` is true, a 32-bit big-endian length header is first
   * prepended. The length value includes the 4 bytes of the length field itself.
   * When `char` is provided, that single character is prepended before joining.
   *
   * @param appendLength - If true, prepends a 32-bit length header before joining.
   * @param char - Optional single character to prepend (e.g. a message type identifier).
   * @returns A new Buffer containing the concatenated contents.
   */
  public join(appendLength?: boolean, char?: string): Buffer {
    let length = this.getByteLength()

    // Prepend a 32-bit big-endian length header that includes its own 4 bytes.
    if (appendLength) {
      this.addInt32(length + 4, true)
      return this.join(false, char)
    }

    // Optionally prepend a leading character (e.g. a message type identifier).
    if (char) {
      this.addChar(char, true)
      length++
    }

    // Allocate a result buffer large enough for all accumulated buffers.
    const result = Buffer.alloc(length)
    let index = 0

    // Copy each buffer into the result buffer sequentially.
    this.buffers.forEach(function (buffer) {
      buffer.copy(result, index, 0)
      index += buffer.length
    })

    return result
  }
}